<?php\n/**\n * Scraper para o site CCCRJ\n * Este script faz o scraping do site http://www.cccrj.com.br/\n * salvando todos os conteúdos e páginas secundárias em arquivos locais\n */\n\nclass CCCRJScraper {\n    private $baseUrl = \"http://www.cccrj.com.br/\";\n    private $outputDir = \"cccrj_content\";\n    private $visitedUrls = [];\n    private $delay = 1; // segundos entre requisições\n\n    public function __construct() {\n        // Criar diretório de saída\n        if (!file_exists($this->outputDir)) {\n            mkdir($this->outputDir, 0755, true);\n        }\n    }\n\n    private function isValidUrl($url) {\n        // Verificar se a URL pertence ao domínio do site\n        return strpos($url, $this->baseUrl) === 0;\n    }\n\n    private function normalizeUrl($url) {\n        // Remover fragmentos e normalizar a URL\n        $url = strtok($url, '#');\n        return $url;\n    }\n\n    private function getPage($url) {\n        $context = stream_context_create([\n            'http' => [\n                'method' => 'GET',\n                'header' => [\n                    'User-Agent: Mozilla/5.0 (compatible; CCCRJ-Scraper/1.0; +http://www.cccrj.com.br/)',\n                    'Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'\n                ],\n                'timeout' => 30\n            ]\n        ]);\n\n        $content = @file_get_contents($url, false, $context);\n        return $content;\n    }\n\n    private function saveContent($content, $path) {\n        // Criar diretório se não existir\n        $fullPath = $this->outputDir . $path;\n        $dir = dirname($fullPath);\n        \n        if (!file_exists($dir)) {\n            mkdir($dir, 0755, true);\n        }\n\n        file_put_contents($fullPath, $content);\n        echo \"Salvo: $fullPath\\n\";\n    }\n\n    private function extractLinks($html, $baseUrl) {\n        $links = [];\n        $dom = new DOMDocument();\n        \n        // Suprimir erros de HTML inválido\n        libxml_use_internal_errors(true);\n        $dom->loadHTML($html);\n        libxml_clear_errors();\n        \n        $xpath = new DOMXPath($dom);\n        \n        // Extrair links de âncoras, imagens, scripts e folhas de estilo\n        $elements = $xpath->query('//a[@href]|//link[@href]|//script[@src]|//img[@src]');\n        \n        foreach ($elements as $element) {\n            $attr = $element->nodeName === 'img' ? 'src' : \n                   ($element->nodeName === 'script' ? 'src' : 'href');\n            $href = $element->getAttribute($attr);\n            \n            if ($href) {\n                $fullUrl = $this->resolveUrl($href, $baseUrl);\n                if ($fullUrl && $this->isValidUrl($fullUrl)) {\n                    $normalizedUrl = $this->normalizeUrl($fullUrl);\n                    if (!in_array($normalizedUrl, $this->visitedUrls)) {\n                        $links[] = $normalizedUrl;\n                    }\n                }\n            }\n        }\n        \n        return array_unique($links);\n    }\n\n    private function resolveUrl($url, $baseUrl) {\n        // Resolver URLs relativas\n        if (preg_match('/^https?:\\/\\//', $url)) {\n            // URL absoluta\n            return $url;\n        } elseif (preg_match('/^\\//', $url)) {\n            // Caminho absoluto\n            $parsed = parse_url($baseUrl);\n            return $parsed['scheme'] . '://' . $parsed['host'] . $url;\n        } else {\n            // Caminho relativo\n            $path = dirname(parse_url($baseUrl, PHP_URL_PATH)) . '/' . $url;\n            $path = $this->normalizePath($path);\n            $parsed = parse_url($baseUrl);\n            return $parsed['scheme'] . '://' . $parsed['host'] . $path;\n        }\n    }\n\n    private function normalizePath($path) {\n        $path = str_replace('\\\\', '/', $path);\n        $parts = explode('/', $path);\n        $normalized = [];\n        \n        foreach ($parts as $part) {\n            if ($part === '' || $part === '.') {\n                continue;\n            } elseif ($part === '..') {\n                array_pop($normalized);\n            } else {\n                $normalized[] = $part;\n            }\n        }\n        \n        return '/' . implode('/', $normalized);\n    }\n\n    public function scrapePage($url) {\n        if (in_array($url, $this->visitedUrls)) {\n            return [];\n        }\n\n        echo \"Scraping: $url\\n\";\n\n        $content = $this->getPage($url);\n        if ($content === false) {\n            echo \"Erro ao obter: $url\\n\";\n            return [];\n        }\n\n        // Determinar caminho do arquivo com base na URL\n        $parsedUrl = parse_url($url);\n        $path = $parsedUrl['path'];\n        \n        if (!$path || $path === '/') {\n            $path = '/index.htm';\n        }\n        \n        // Salvar conteúdo\n        $this->saveContent($content, $path);\n        \n        // Marcar como visitado\n        $this->visitedUrls[] = $url;\n\n        // Extrair links se for uma página HTML\n        $links = [];\n        if (strpos($content, '<html') !== false || strpos($content, '<!DOCTYPE') !== false) {\n            $links = $this->extractLinks($content, $url);\n        }\n        \n        // Respeitar delay entre requisições\n        sleep($this->delay);\n        \n        return $links;\n    }\n\n    public function downloadFile($url) {\n        if (in_array($url, $this->visitedUrls)) {\n            return;\n        }\n\n        echo \"Baixando: $url\\n\";\n\n        $content = $this->getPage($url);\n        if ($content === false) {\n            echo \"Erro ao baixar: $url\\n\";\n            return;\n        }\n\n        // Determinar caminho do arquivo com base na URL\n        $parsedUrl = parse_url($url);\n        $path = $parsedUrl['path'];\n        \n        // Salvar conteúdo do arquivo\n        $this->saveContent($content, $path);\n        \n        // Marcar como visitado\n        $this->visitedUrls[] = $url;\n        \n        // Respeitar delay entre requisições\n        sleep($this->delay);\n    }\n\n    public function getAllSiteUrls() {\n        // URLs baseadas na estrutura identificada do site\n        return [\n            $this->baseUrl,\n            $this->baseUrl . \"index.htm\",\n            $this->baseUrl . \"mapa.htm\",\n            $this->baseUrl . \"fale.htm\",\n            $this->baseUrl . \"Style.css\",\n            $this->baseUrl . \"javascript/jquery.s.min.js\",\n            $this->baseUrl . \"boletim.pdf\",\n            $this->baseUrl . \"Manual_PERT_Simples_Nacional.pdf\",\n            \n            // Seção CCCRJ\n            $this->baseUrl . \"cccrj/inicio.htm\",\n            $this->baseUrl . \"cccrj/constituicao.htm\",\n            $this->baseUrl . \"cccrj/lancamento.htm\",\n            $this->baseUrl . \"cccrj/estatuto.htm\",\n            $this->baseUrl . \"cccrj/centenario.htm\",\n            $this->baseUrl . \"cccrj/diretorias.htm\",\n            \n            // Seção CRMC\n            $this->baseUrl . \"crmc/inicio.htm\",\n            $this->baseUrl . \"crmc/cafeteria.htm\",\n            $this->baseUrl . \"crmc/cafeteria/carta.htm\",\n            $this->baseUrl . \"crmc/cafeteria/fotos.htm\",\n            $this->baseUrl . \"crmc/biblioteca.htm\",\n            $this->baseUrl . \"crmc/acervo/frame_acervo.htm\",\n            $this->baseUrl . \"crmc/cultural.htm\",\n            $this->baseUrl . \"crmc/cultural/exposicao.htm\",\n            $this->baseUrl . \"crmc/dicas.htm\",\n            $this->baseUrl . \"crmc/dicas_curiosidades.htm\",\n            \n            // Seção Revista\n            $this->baseUrl . \"revista/inicio.htm\",\n            $this->baseUrl . \"revista/acervo/Frame_acervo.htm\",\n            \n            // Seção Terminal\n            $this->baseUrl . \"terminal/inicio.htm\",\n            \n            // Seção Rio\n            $this->baseUrl . \"rio/inicio.htm\",\n            $this->baseUrl . \"rio/historia.htm\",\n            $this->baseUrl . \"rio/producao.htm\",\n            $this->baseUrl . \"rio/exportacao.htm\",\n            \n            // Seção Boletim\n            $this->baseUrl . \"Boletim/index.php\",\n            \n            // Seções de clipping e notícias\n            $this->baseUrl . \"clipping/frame_clipping.htm\",\n            $this->baseUrl . \"noticias/frame_noticias.htm\",\n            \n            // Seção de links\n            $this->baseUrl . \"links/inicio.htm\",\n        ];\n    }\n\n    public function run() {\n        echo \"Iniciando scraper do site CCCRJ...\\n\";\n        \n        $allUrls = $this->getAllSiteUrls();\n        echo \"Encontradas \" . count($allUrls) . \" URLs para processar\\n\";\n        \n        foreach ($allUrls as $url) {\n            try {\n                $ext = pathinfo(parse_url($url, PHP_URL_PATH), PATHINFO_EXTENSION);\n                \n                if (in_array($ext, ['pdf', 'jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp'])) {\n                    // Baixar arquivo\n                    $this->downloadFile($url);\n                } else {\n                    // Scraping de página\n                    $this->scrapePage($url);\n                }\n            } catch (Exception $e) {\n                echo \"Erro processando $url: \" . $e->getMessage() . \"\\n\";\n            }\n        }\n        \n        // Criar arquivo de resumo\n        $summaryPath = $this->outputDir . '/resumo_scraping.txt';\n        $summary = \"Resumo do Scraping do Site CCCRJ\\n\";\n        $summary .= str_repeat(\"=\", 40) . \"\\n\";\n        $summary .= \"Data do scraping: \" . date('Y-m-d H:i:s') . \"\\n\";\n        $summary .= \"URL base: \" . $this->baseUrl . \"\\n\";\n        $summary .= \"Total de páginas/arquivos processados: \" . count($this->visitedUrls) . \"\\n\";\n        $summary .= \"\\nPáginas/arquivos salvos:\\n\";\n        \n        foreach ($this->visitedUrls as $url) {\n            $summary .= \"- $url\\n\";\n        }\n        \n        file_put_contents($summaryPath, $summary);\n        \n        echo \"Scraping concluído! \" . count($this->visitedUrls) . \" páginas/arquivos processados.\\n\";\n        echo \"Conteúdo salvo em: \" . $this->outputDir . \"\\n\";\n    }\n}\n\n// Executar o scraper\n$scraper = new CCCRJScraper();\n$scraper->run();\n\n?>